const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Lago Hermoso, Argentina (approximately -38.5, -69.5)
  const lagoHermoso = ee.Geometry.Point([-69.5, -38.5]).buffer(5000);

  // Date 1: March 29, 1987 (morning) - Use Landsat 5 TM
  const date1Start = '1987-03-29';
  const date1End = '1987-03-30';

  // Date 2: February 15, 2001 - Use Landsat 7 ETM+
  const date2Start = '2001-02-15';
  const date2End = '2001-02-16';

  // Attempt Landsat 5 for 1987
  let col1 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(lagoHermoso)
    .filterDate(date1Start, date1End)
    .select('QA_PIXEL');

  let size1 = col1.size().getInfo();
  console.log(`1987-03-29 Landsat 5: ${size1} images`);

  if (size1 === 0) {
    console.log("No Landsat 5 data for 1987. Trying Landsat 4...");
    col1 = ee.ImageCollection('LANDSAT/LT04/C02/T1_L2')
      .filterBounds(lagoHermoso)
      .filterDate(date1Start, date1End)
      .select('QA_PIXEL');
    size1 = col1.size().getInfo();
    console.log(`1987-03-29 Landsat 4: ${size1} images`);
  }

  // Landsat 7 for 2001
  let col2 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(lagoHermoso)
    .filterDate(date2Start, date2End)
    .select('QA_PIXEL');

  let size2 = col2.size().getInfo();
  console.log(`2001-02-15 Landsat 7: ${size2} images`);

  if (size1 === 0 || size2 === 0) {
    console.log("Empty Collection: Missing data for one or both dates");
    console.log("C1");
    return;
  }

  // Calculate cloud percentage for each image
  // QA_PIXEL bit 3 (cloud) and bit 4 (cloud shadow)
  const getCloudPercentage = (image) => {
    const qa = image.select('QA_PIXEL');
    const cloudBit = 3;
    const shadowBit = 4;

    const cloud = qa.bitwiseAnd(Math.pow(2, cloudBit)).neq(0);
    const shadow = qa.bitwiseAnd(Math.pow(2, shadowBit)).neq(0);
    const cloudMask = cloud.or(shadow);

    const totalPixels = qa.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: lagoHermoso,
      scale: 30,
      maxPixels: 1e9
    }).get('QA_PIXEL');

    const cloudPixels = cloudMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: lagoHermoso,
      scale: 30,
      maxPixels: 1e9
    }).get('QA_PIXEL');

    return ee.Dictionary({
      totalPixels: totalPixels,
      cloudPixels: cloudPixels
    });
  };

  // Get first image from each collection
  const img1 = ee.Image(col1.first());
  const img2 = ee.Image(col2.first());

  const stats1 = getCloudPercentage(img1).getInfo();
  const stats2 = getCloudPercentage(img2).getInfo();

  console.log(`Stats1 Total: ${stats1.totalPixels}, Cloud: ${stats1.cloudPixels}`);
  console.log(`Stats2 Total: ${stats2.totalPixels}, Cloud: ${stats2.cloudPixels}`);

  if (stats1.totalPixels === null || stats2.totalPixels === null || 
      stats1.cloudPixels === null || stats2.cloudPixels === null) {
    console.log("Calculation Failure: Null pixel counts");
    console.log("C3");
    return;
  }

  if (stats1.totalPixels === 0 || stats2.totalPixels === 0) {
    console.log("No Valid Pixels");
    console.log("C2");
    return;
  }

  const cloudPct1 = (stats1.cloudPixels / stats1.totalPixels) * 100;
  const cloudPct2 = (stats2.cloudPixels / stats2.totalPixels) * 100;

  console.log(`1987-03-29 Cloud Cover: ${cloudPct1.toFixed(2)}%`);
  console.log(`2001-02-15 Cloud Cover: ${cloudPct2.toFixed(2)}%`);

  if (cloudPct1 > cloudPct2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
